/* ②b 摆好前置状态 —— bf-12 修的就是这一步。
   ⚠ 根因：localStorage.clear() 之后是**全新档**，全员好感 0 → 9 张卡全灰 →
     面板里没有一张 data-ok="1" 的卡 → 选不了对象 → 后面每步都拿不到东西 →
     errors 一堆 → 降级到 mshta 模式 B（看起来就像「模式 A 进不去」）。
   做法照抄 tools/bf/e2e-audio.js：用页面自己的调试钩子 CS2_DEBUG.mjSet 摆好感。
   摆法刻意覆盖三种分支：可送（20~79）/ 太生疏（<20）/ 已满（≥80）。 */
const setup = await ev(`(function(){
  if (!window.CS2_DEBUG || !window.CS2_DEBUG.mjSet) return "no-debug";
  window.CS2_DEBUG.mjSet({
    bonds: { fang:42, su:38, lin:55, wen:24, lei:0, hong:85, guo:31, lu:0, man:0 },
    breakfastDay: { day: window.__cs2.S.day, sent: [] }
  });
  var b = window.__cs2.S.bonds, n = 0, ks = Object.keys(b);
  for (var i = 0; i < ks.length; i++) if (b[ks[i]] >= 20 && b[ks[i]] < 80) n++;
  return "ok:" + n;
})()`);
info.setup = setup;
A(setup === "ok:5", "前置状态已摆好：5 位可送（20~79）/ 3 位太生疏 / 1 位已满", String(setup));

const btn = await ev("!!document.getElementById('bfBtn')");

