/* ⑥b 练手局（bf-12）：**门槛外的角色也能开局，且好感 / 每日一次一个字都不变**
   用 man（好感 0 = 用户实测被卡住的那种角色）：正常门槛必拒，练手局必须放行。
   证据链两层：
     · 门槛层：bfCanSend("man") 不 ok；不带 force 的 debug 开局同样 false；bfPractice 才 true
     · 数值层：打完整局之后 S.bonds / S.breakfastDay **逐字段深比**没变，
               而且面板里 man 仍显示「太生疏」而不是「今天已经送过」。 */
const bondsP0 = await ev("JSON.stringify(window.__cs2.S.bonds)");
const bfDayP0 = await ev("JSON.stringify(window.__cs2.S.breakfastDay)");
const gateMan = await ev('JSON.stringify(window.bfCanSend("man"))');
A(/"ok":false/.test(String(gateMan)), "练手局对照：man 好感 0 走正常门槛必被拒（就是用户被卡住的情形）", String(gateMan));
A(await ev('window.__cs2.bfStart("man", {})') === false, "练手局对照：不带 force 的 debug 开局同样被门槛拒绝");
A(await ev('window.__cs2.bfPractice("man")') === true, "练手局：好感 0 的角色也能开局（practice + force 绕开门槛）");
await sleep(900);
const stP = JSON.parse(await ev("JSON.stringify(window.__cs2.bfState)"));
A(!!stP && stP.running === true && stP.practice === true, "练手局状态正确（running / practice=true）",
  JSON.stringify(stP && { practice: stP.practice, target: stP.target && stP.target.name }));
const pRun = JSON.parse(await ev("JSON.stringify(" + DRIVER_JS + ")"));
A(pRun.done === true && pRun.after && pRun.after.over === true, "练手局 debug 驱动跑完整局（已结算）");
await sleep(500);
const pPanel = await ev('(function(){var e=document.querySelector("#bfGameHost .bf-result"); return e? e.innerText.replace(/\\n+/g," | ") : "";})()');
info.practicePanel = String(pPanel).slice(0, 400);
A(/练手局/.test(String(pPanel)) && /不影响好感/.test(String(pPanel)), "★ 练手局结算面板明确标注「练手局 · 不影响好感」");
A(/不变/.test(String(pPanel)), "★ 结算面板里好感那一行写「不变（练手局）」（不是 +6）");
const pRes = JSON.parse(await ev("JSON.stringify(window.__cs2.bfResult)"));
A(!!pRes && pRes.practice === true && pRes.bondDelta === 0, "练手局结算结果 practice=true / bondDelta=0",
  pRes && ("practice=" + pRes.practice + " delta=" + pRes.bondDelta));
await png("bf_practice.png");
await ev('(function(){var b=document.querySelector("#bfGameHost .bf-result [data-act=close]"); if(b) b.click();})()');
await sleep(500);
const bondsP1 = await ev("JSON.stringify(window.__cs2.S.bonds)");
const bfDayP1 = await ev("JSON.stringify(window.__cs2.S.breakfastDay)");
info.practiceBonds = { before: bondsP0, after: bondsP1 };
info.practiceBfDay = { before: bfDayP0, after: bfDayP1 };
A(bondsP1 === bondsP0, "★ 练手局结束后 S.bonds 逐字段完全没变（" + bondsP0 + "）");
A(bfDayP1 === bfDayP0, "★ 练手局结束后 S.breakfastDay 没变（没写「今天已送」）（" + bfDayP0 + "）");
await ev('document.getElementById("bfBtn").click()');
await sleep(500);
const manCard = await ev(`(function(){var c=document.querySelector('#bfPickHost .bf-card[data-id="man"]'); return c? (c.getAttribute("data-ok")+"|"+c.innerText.replace(/\\n+/g," ")) : "MISSING";})()`);
info.manCardAfterPractice = manCard;
A(/^0\|/.test(String(manCard)) && /生疏/.test(String(manCard)),
  "★ 练手局后 man 仍显示「太生疏」而不是「今天已经送过」", String(manCard));
await ev('document.querySelector("#bfPickHost .bf-btn").click()');
await sleep(300);

/* ⑦ 失败路径：换一位对象，让所有顾客跑掉 */

  /* ⚠ ok:false 有两种，必须分清楚：
       ① Chrome 起不来 —— 上面提前 return，带 why；
       ② Chrome 起来了但断言没过 —— 这时也要把**第一批失败项**带出去，
          否则主流程只会打印「（undefined）」，看的人完全不知道发生了什么（bf-12 前一直如此）。 */
  return { ok: errors.length === 0, checks, errors, info,
    why: errors.length ? ("模式 A 起来了但断言未过 " + errors.length + " 项：" + errors.slice(0, 3).join(" ／ ")) : "" };
}

/* BF_E2E_MODE_B=1：强制走模式 B。
   模式 A 修好之后模式 B 平时不会再被触发 —— 没有这个开关就**没法证明降级路径仍然可用**
   （向后兼容要能真跑出来，不能只靠读代码）。默认不设 → 行为与以前完全一样。 */
const FORCE_B = String(process.env.BF_E2E_MODE_B || "") === "1";
let ch = { ok: false, why: FORCE_B ? "BF_E2E_MODE_B=1 强制走模式 B（验证降级路径仍然可用）" : "未执行" };
if (!FORCE_B) { try { ch = await runChrome(); } catch (e) { ch = { ok: false, why: "Chrome 流程异常：" + (e && e.message || e) }; } }
